import * as E from './engine.mjs';
const VERSION='1.1.0',KEY='territoires.save.v1';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3V6Z"/><path d="M9 3v15M15 6v15"/>',book:'<path d="M12 5c-3-2-7-2-10-1v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1ZM12 5v15"/>',bag:'<rect x="4" y="7" width="16" height="14" rx="3"/><path d="M8 7V5a4 4 0 0 1 8 0v2M4 12h16M9 12v3h6v-3"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="9" cy="18" r="2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',check:'<path d="m5 12 4 4L20 5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1 3-6Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',leaf:'<path d="M20 3C6 1 1 12 7 18S23 16 20 3ZM5 21 17 8"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.book}</svg>`;
let data,state,route={view:'home',id:''},quiz=null,bookReturnFocus=null,toastTimer,offlineStatus='Non téléchargé',bookFilters={query:'',domain:'',collection:false};
let sourceLookup={};
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{notify('Sauvegarde locale indisponible : exportez votre progression.');return false;}}
function settings(){document.documentElement.style.setProperty('--scale',state.settings.font);document.body.classList.toggle('reduced',!state.settings.motion);}
function nav(view,id=''){quiz=null;location.hash=view+(id?'/'+encodeURIComponent(id):'');if(route.view===view&&route.id===id)render();}
function parseRoute(){const [v,id]=location.hash.slice(1).split('/');let decoded='';try{decoded=decodeURIComponent(id||'');}catch{}route={view:v==='main'?'home':v||'home',id:decoded};quiz=null;closeBook(false);render();window.scrollTo(0,0);}
function header(){ $('#header').innerHTML=`<button class="brand" data-go="home" aria-label="Territoires, accueil">${icon('leaf')}<span><strong>TERRITOIRES</strong><small>Une aventure pour apprendre</small></span></button><div class="headright"><span class="xp">${E.xp(state)} XP</span><button class="iconbtn" data-go="settings" aria-label="Réglages">${icon('settings')}</button></div>`;$('#nav').innerHTML=[['home','map','Explorer'],['library','book','Bibliothèque'],['hero','user','Personnage'],['bag','bag','Sacoche']].map(([v,i,t])=>`<button data-go="${v}" class="${(route.view===v||(v==='home'&&['chapter','mission','side','review','story','journal','aftermath'].includes(route.view)))?'active':''}" ${route.view===v?'aria-current="page"':''}>${icon(i)}${t}</button>`).join('');}
function btn(text,action,id='',style=''){return `<button class="btn ${style}" data-action="${action}" data-id="${esc(id)}">${text}</button>`;}
function goBtn(text,view,id='',style=''){return `<button class="btn ${style}" data-go="${view}" data-id="${esc(id)}">${text}</button>`;}
function sources(ids){return `<div class="source-links">${[...new Set(ids||[])].map(id=>sourceLookup[id]).filter(Boolean).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`).join('')}</div>`;}
function scene(ch,title,sub,buttons='',short=false){return `<section class="hero ${short?'short':''}"><img src="./assets/${ch.scene}.webp" alt="${esc({opening:'La manufacture réhabilitée accueille ses habitants',office:'Bureau de la DGS dans l’annexe face à la mairie',archive:'Salle de lecture des archives municipales',manufacture:'La manufacture avant sa réhabilitation',council:'Salle du conseil avant la séance',town:'La place et la mairie de Valrivière',library:'La médiathèque ouverte sur la ville',finance:'Une réunion au service des finances',meeting:'Un échange entre collègues',river:'Les berges de Valrivière',forum:'Un forum de quartier à la tombée du jour'}[ch.scene])}" fetchpriority="high"><span class="hero-badge">VALRIVIÈRE · ${esc(ch.domain)}</span><div class="hero-inner"><span class="eyebrow">${short?'Les dossiers du territoire':'Votre aventure commence ici'}</span><h1>${esc(title)}</h1><p>${esc(sub)}</p><div class="actions">${buttons}</div></div></section>`;}
function nextMission(){return E.index(data).missions.find(m=>!state.completed.includes(m.id)&&E.unlocked(data,state,m.id));}
function originalHome(){const next=nextMission(),due=E.due(data,state),st=E.stats(data,state);return scene(data.chapters[0],state.completed.length?'Un territoire. Mille choses à apprendre.':'Votre savoir change la ville.','Rencontrez ses habitants, ouvrez les livres et faites grandir vos connaissances, dossier après dossier.',next?goBtn(state.completed.length?'Poursuivre l’aventure '+icon('arrow'):'Entrer à Valrivière '+icon('arrow'),'mission',next.id,'gold')+goBtn('Découvrir la bibliothèque','library','','ghost'):goBtn('Revoir mes connaissances','review','','gold'))+`<div class="wrapper"><div class="ribbon"><div><strong>${state.completed.length?'Votre carnet prend vie':'Bienvenue, '+esc(state.profile.name)}</strong><p>${state.completed.length} / ${E.index(data).missions.length} dossiers résolus · ${state.collected.length} livres dans la sacoche · ${st.consolidated} réponses consolidées</p></div>${due.length?goBtn(`${due.length} révisions du jour ${icon('arrow')}`,'review','','light'):goBtn('Mon personnage '+icon('arrow'),'hero','','light')}</div><div class="section-title"><div><span class="eyebrow">Le territoire vous attend</span><h2>Choisissez votre destination</h2></div><p>6 lieux à explorer<br>Les premiers dossiers sont ouverts</p></div><div class="chapter-grid">${data.chapters.map((c,i)=>{const n=c.missions.filter(m=>state.completed.includes(m.id)).length;return `<button class="chapter-card" data-go="chapter" data-id="${c.id}"><div class="chapter-image"><img src="./assets/${c.scene}.webp" alt="" loading="lazy"><span class="chapter-number">0${i+1}</span></div><div class="card-copy"><span class="eyebrow">${esc(c.domain)}</span><h3>${esc(c.title)}</h3><p>${esc(c.subtitle)}</p><div class="progress"><span style="width:${n/c.missions.length*100}%"></span></div><div class="row smalltext"><span>${n} / ${c.missions.length} dossiers</span>${icon(n===c.missions.length?'check':'arrow')}</div></div></button>`;}).join('')}</div><div class="divider"></div><div class="row"><p class="fine">Des connaissances à découvrir, des dossiers à résoudre.<br>Parcours ${state.profile.path==='externe'?'externe':'troisième concours'} · Administration générale.</p>${goBtn('Repères concours','resources','','ghost small')}</div></div>`;}
function chapter(){const c=data.chapters.find(x=>x.id===route.id);if(!c)return notFound();const sides=(data.sideQuests||[]).filter(x=>x.chapterId===c.id);return scene(c,c.title,c.subtitle,'',true)+`<div class="wrapper"><button class="back" data-go="home">${icon('back')} Carte du territoire</button><div class="mentor"><span class="eyebrow">${esc(c.mentor)}</span>${esc(c.intro)}</div><div class="section-title"><h2>Votre parcours</h2><p>Lire · Comprendre · Agir</p></div><div class="mission-list">${c.missions.map((m,i)=>{const done=state.completed.includes(m.id),open=E.unlocked(data,state,m.id);return `<article class="mission-card ${open?'':'locked'}"><span class="step">${done?icon('check'):open?i+1:icon('lock')}</span><div class="body"><h3>${esc(m.title)}</h3><p>${done?'Dossier résolu':open?'Une lecture essentielle · 3 questions':'À venir dans la campagne'}</p></div>${open?goBtn(done?'Revoir':'Ouvrir','mission',m.id,done?'light':''):''}</article>`;}).join('')}</div><div class="section-title"><h2>Hors des sentiers battus</h2></div>${sides.map(x=>`<article class="panel"><span class="eyebrow">Quête secondaire · ${state.side.includes(x.id)?'Accomplie':'Facultative'}</span><h3>${esc(x.title)}</h3><p>${esc(x.story)}</p>${goBtn(state.side.includes(x.id)?'Relire':'Découvrir','side',x.id,'light')}</article>`).join('')}</div>`;}
function bookButton(id){const b=data.books.find(x=>x.id===id);if(!b)return '';return `<button class="book-button" data-action="book" data-id="${b.id}"><span class="book-icon ${b.optional?'optional':''}">${icon('book')}</span><span><strong>${esc(b.title)}</strong><small>${state.read.includes(b.id)?'Lecture marquée comme terminée':b.optional?'Lecture facultative':'Lecture essentielle'} · ${Math.max(1,Math.ceil(b.paragraphs.join(' ').split(/\s+/).length/180))} min</small></span>${state.read.includes(b.id)?icon('check'):''}</button>`;}
function mission(){const m=E.getMission(data,route.id);if(!m)return notFound();const c=data.chapters.find(c=>c.id===m.chapterId);if(!E.unlocked(data,state,m.id))return `<div class="wrapper"><h1>Dossier à venir</h1><p>Le récit suit un ordre chronologique. Retrouvez le prochain dossier dans votre carnet.</p>${goBtn('Poursuivre la campagne','journal')}${goBtn('Retour au chapitre','chapter',c.id)}</div>`;state.lastMission=m.id;persist();const done=state.completed.includes(m.id),read=m.requiredBooks.every(id=>state.read.includes(id)),correct=m.questions.filter(q=>state.answers[q.id]?.correct).length;const n=data.campaign?.missions[m.id];return scene({...c,scene:n?.scene||c.scene},m.title,n?n.time+' · '+n.place:m.story,'',true)+`<div class="wrapper"><button class="back" data-go="chapter" data-id="${c.id}">${icon('back')} ${esc(c.title)}</button>${n?storyPanel(m,n):''}${done?`<div class="ribbon"><div><strong>Dossier résolu</strong><p>${esc(n?.outcome||m.outro)}</p></div>${icon('check')}</div>`:''}<div class="two-col" ${n&&!storySeen(m.id)?'hidden':''}><section class="panel"><span class="eyebrow">01 · Préparer le dossier</span><h2>Les lectures de votre mission</h2><p class="muted">Prenez connaissance du document. Il restera accessible pendant les questions.</p>${m.requiredBooks.map(bookButton).join('')}${m.optionalBooks.length?`<div class="divider"></div><span class="eyebrow">Pour aller plus loin</span>${m.optionalBooks.map(bookButton).join('')}`:''}</section><section class="panel"><span class="eyebrow">02 · Mobiliser vos connaissances</span><h2>À vous de proposer</h2><p>Trois questions pour préparer une réponse au dossier. Chaque choix est expliqué et relié à ses sources.</p><div class="progress"><span style="width:${correct/m.questions.length*100}%"></span></div><p class="smalltext">${correct} / ${m.questions.length} réponses résolues</p>${read?btn(done?'Rejouer les questions':correct===m.questions.length?'Voir le bilan':'Traiter le dossier','start',m.id):`<p class="tag">${icon('book')} Terminez la lecture essentielle</p>`}<p class="fine" style="margin-top:18px">La consultation des livres est autorisée. Votre première réponse et vos reprises sont distinguées.</p></section></div></div>`;}
function startQuiz(ids,kind,id){quiz={ids,kind,id,pos:0,feedback:null,selected:null,results:[]};if(kind==='mission'&&!state.completed.includes(id)){const p=ids.findIndex(id=>!state.answers[id]?.correct);quiz.pos=p<0?ids.length:p;}renderQuiz();}
function renderQuiz(){header();const qid=quiz.ids[quiz.pos];if(!qid){$('#main').innerHTML=quizEnd();return;}const q=E.index(data).questions.find(x=>x.id===qid);const m=E.index(data).missions.find(m=>m.questions.some(x=>x.id===qid));const related=m?m.requiredBooks:(data.sideQuests||[]).filter(s=>s.question.id===qid).map(s=>s.bookId);const f=quiz.feedback;$('#main').innerHTML=`<div class="wrapper"><div class="quiz"><button class="back" data-action="quitquiz">${icon('back')} Revenir au dossier</button><div class="row"><span class="eyebrow">${quiz.kind==='review'?'Révision':quiz.kind==='practice'?'Défi de connaissances':quiz.kind==='side'?'Quête secondaire':'Le dossier avance'}</span><span class="tag">${quiz.pos+1} / ${quiz.ids.length}</span></div><div class="progress"><span style="width:${quiz.pos/quiz.ids.length*100}%"></span></div>${questionScene(q,m)}<h2 tabindex="-1" id="question-title">${esc(q.prompt)}</h2><div class="choices">${q.choices.map((t,i)=>`<button class="choice ${f!==null?(i===q.answer?'correct':quiz.selected===i?'wrong':''):''}" data-answer="${i}" ${f!==null?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${esc(t)}</button>`).join('')}</div>${f!==null?`<div class="feedback ${f?'':'wrong'}" role="status"><strong>${f?'Bien compris.':'Prenons le temps de comprendre.'}</strong><p>${esc(q.explanation)}</p><details><summary>Consulter les références</summary>${sources(q.sourceIds)}</details></div><div class="actions">${btn(f||quiz.kind==='practice'?'Continuer '+icon('arrow'):'Réessayer','nextq')}${f?'':btn('Relire le document','book',related[0],'light')}</div>`:''}<div class="divider"></div><span class="eyebrow">Dans votre sacoche</span>${related.map(bookButton).join('')}<div class="actions" style="margin-top:16px">${(data.codeEntries||[]).filter(c=>c.sourceIds.some(id=>q.sourceIds.includes(id))).map(c=>btn(esc(c.code)+' · '+esc(c.article),'code',c.id,'light small')).join('')}</div><p class="fine">${quiz.kind==='practice'?'Ce défi utilise les questions de la campagne. Il ne constitue pas une annale officielle.':'Vous pouvez consulter vos documents sans quitter cette question.'}</p></div></div>`;window.scrollTo(0,0);}
function quizEnd(){const m=quiz.kind==='mission'?E.getMission(data,quiz.id):null;const first=quiz.ids.filter(id=>state.answers[id]?.firstCorrect).length;return `<div class="wrapper"><div class="quiz finish">${icon('star')}<span class="eyebrow">Une étape de plus</span><h2>${quiz.kind==='mission'?'Votre dossier est prêt':quiz.kind==='side'?'Une découverte à conserver':'Votre séance est terminée'}</h2><p>${m?esc(data.campaign?.missions[m.id]?.outcome||m.outro):quiz.kind==='side'?esc(data.campaign?.sideQuests[quiz.id]?.outcome||'Une découverte à conserver.'):'Retrouvez les lectures et les corrections dans votre bibliothèque.'}</p>${quiz.kind==='practice'?`<p>${quiz.results.filter(Boolean).length} / ${quiz.results.length} bonnes réponses dans cette séance.</p>`:`<p>${first} / ${quiz.ids.length} réussites dès la toute première réponse.</p>`}${quiz.kind==='mission'?btn('Valider le dossier · +60 XP','complete',quiz.id):quiz.kind==='side'?btn('Accomplir la quête · +30 XP','complete-side',quiz.id):goBtn('Retour au territoire','home')}<p class="fine" style="margin-top:20px">Les points sont attribués une seule fois. La consolidation se construit avec des révisions espacées.</p></div></div>`;}
function side(){const x=(data.sideQuests||[]).find(x=>x.id===route.id);if(!x)return notFound();const c=data.chapters.find(c=>c.id===x.chapterId),n=data.campaign?.sideQuests[x.id];return scene(c,x.title,n?.context||x.story,'',true)+`<div class="wrapper"><button class="back" data-go="chapter" data-id="${c.id}">${icon('back')} Retour au chapitre</button><div class="panel"><span class="eyebrow">Une lecture à collectionner</span>${bookButton(x.bookId)}<div class="divider"></div><h2>${esc(n?characterName(n.character):'Le mot du mentor')}</h2><p>${esc(n?.questionContext||'Une question vous invite à réutiliser cette découverte.')}</p>${state.read.includes(x.bookId)?btn(state.side.includes(x.id)?'Rejouer le défi':'Relever le défi','start-side',x.id):'<span class="tag">Commencez par la lecture</span>'}</div></div>`;}
function bookTile(b){return `<button class="book-tile" data-action="book" data-id="${b.id}"><span class="book-icon ${b.optional?'optional':''}">${icon('book')}</span><span class="eyebrow">${esc(b.domain)}</span><h3>${esc(b.title)}</h3><small>${state.read.includes(b.id)?'✓ Lu':state.collected.includes(b.id)?'Dans votre sacoche':b.optional?'À découvrir · Facultatif':'À découvrir'}</small></button>`;}
function filteredBooks(){const q=bookFilters.query.toLocaleLowerCase('fr');return data.books.filter(b=>(!bookFilters.collection||state.collected.includes(b.id))&&(!bookFilters.domain||b.domain===bookFilters.domain)&&(!q||(b.title+' '+b.paragraphs.join(' ')).toLocaleLowerCase('fr').includes(q)));}
function library(){const domains=[...new Set(data.books.map(b=>b.domain))];return `<div class="wrapper"><div class="page-intro"><span class="eyebrow">La maison des savoirs</span><h1>Votre bibliothèque</h1><p>Ouvrez un livre pour le glisser dans votre sacoche. Revenez-y librement au fil des dossiers.</p></div><div class="filters"><input id="book-search" type="search" placeholder="Chercher une notion, un livre…" aria-label="Rechercher dans les livres" value="${esc(bookFilters.query)}"><select id="book-domain" aria-label="Filtrer par domaine"><option value="">Tous les domaines</option>${domains.map(d=>`<option ${bookFilters.domain===d?'selected':''}>${esc(d)}</option>`).join('')}</select><button class="btn ${bookFilters.collection?'':'light'}" data-action="collection">${bookFilters.collection?'Ma collection':'Tous les livres'}</button></div><p class="fine" id="book-count">${filteredBooks().length} ouvrages · ${state.read.length} lectures terminées</p><div class="book-grid" id="book-results">${filteredBooks().map(bookTile).join('')}</div></div>`;}
function hero(){const st=E.stats(data,state);return `<div class="wrapper"><div class="character"><img class="portrait" src="./assets/hero.webp" alt="Votre personnage à Valrivière"><div><span class="eyebrow">Votre personnage</span><h1>${esc(state.profile.name)}</h1><span class="tag gold">${E.rank(state)}</span><p class="muted" style="margin-top:16px">Chaque dossier nourrit vos connaissances. Chaque retour sur une notion renforce vos acquis.</p>${goBtn('Personnaliser','settings','','light small')}</div></div><div class="metrics"><div class="metric"><strong>${E.xp(state)}</strong><small>Expérience d’aventure</small></div><div class="metric"><strong>${state.completed.length} / 18</strong><small>Dossiers résolus</small></div><div class="metric"><strong>${state.collected.length} / ${data.books.length}</strong><small>Livres collectionnés</small></div></div><div class="section-title"><h2>Vos connaissances grandissent</h2></div><div class="skill-grid">${data.chapters.filter((c,i,a)=>a.findIndex(x=>x.domain===c.domain)===i).map(c=>{const s=E.stats(data,state,c.domain);return `<article class="skill"><span class="eyebrow">${s.consolidated?'Consolidation en cours':s.correct?'En pratique':s.discovered?'En découverte':'À découvrir'}</span><h3>${esc(c.domain)}</h3><div class="progress"><span style="width:${s.correct/s.total*100}%"></span></div><p>${s.correct} / ${s.total} questions résolues · ${s.consolidated} consolidées</p><p>${s.first} réussites dès la première réponse</p></article>`;}).join('')}</div><p class="fine" style="margin-top:20px">Une réponse est dite consolidée après deux réussites espacées d’au moins un jour. Cela ne garantit pas la maîtrise de tout un domaine. Les XP et rangs appartiennent au jeu ; ils ne prédisent pas votre résultat au concours.</p><div class="ribbon"><div><strong>${E.due(data,state).length} notions à revoir maintenant</strong><p>Revenez sur les erreurs et entretenez votre mémoire.</p></div>${goBtn('Réviser','review','','light')}</div><div class="section-title"><h2>Souvenirs de voyage</h2></div><div class="actions">${(data.sideQuests||[]).map(s=>`<span class="tag ${state.side.includes(s.id)?'gold':''}">${state.side.includes(s.id)?icon('check'):icon('lock')} ${esc(s.title)}</span>`).join('')}</div></div>`;}
function bag(){const codes=data.codeEntries||[];return `<div class="wrapper">${goBtn('Ouvrir le carnet de campagne','journal','','light')}<div class="page-intro"><span class="eyebrow">Toujours à portée de main</span><h1>Votre sacoche</h1><p>Vos lectures, vos repères juridiques et les sources officielles pour approfondir une affaire.</p></div><div class="tabs">${btn('Mes livres','bag-tab','books')}${btn('Codes et repères','bag-tab','codes','light')}${btn('Sources officielles','bag-tab','sources','light')}${goBtn('Repères concours','resources','','light')}</div><section id="bag-books">${state.collected.length?`<div class="book-grid">${data.books.filter(b=>state.collected.includes(b.id)).map(bookTile).join('')}</div>`:`<div class="empty"><h2>La première page vous attend</h2><p>Les livres que vous ouvrez seront conservés ici.</p>${goBtn('Visiter la bibliothèque','library')}</div>`}</section><section id="bag-codes" hidden><div class="panel"><h2>Les codes dans votre sacoche</h2><p>Repères de lecture synthétiques, à compléter par le texte officiel applicable au dossier.</p>${codes.map(c=>`<article class="source-item"><span class="eyebrow">${esc(c.code)} · ${esc(c.article)}</span><h3>${esc(c.title||c.code||c.id)}</h3><p>${esc(c.summary||c.text||c.description||'')}</p>${c.url?`<a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">Ouvrir le texte officiel ↗</a>`:sources(c.sourceIds||[])}</article>`).join('')||sources(data.sources.filter(s=>/code|CGCT|CGFP|constitution/i.test(s.title)).map(s=>s.id))}</div></section><section id="bag-sources" hidden><div class="panel"><h2>Les références du carnet</h2><p class="fine">Synthèses originales et QCM de création. Sources vérifiées pour cette édition au 30 octobre 2026. Les liens externes nécessitent une connexion.</p>${data.sources.map(s=>`<div class="source-item"><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><small>Consulté le ${esc(s.checked)}</small></div>`).join('')}</div></section></div>`;}
function review(){const d=E.due(data,state);return `<div class="wrapper"><div class="page-intro"><span class="eyebrow">Le jardin des connaissances</span><h1>Entretenir vos acquis</h1><p>Les notions reviennent après un délai. Une erreur rapproche la prochaine révision ; les réussites espacées l’éloignent.</p></div><div class="panel"><h2>${d.length?d.length+' questions vous attendent':'Votre carnet est à jour'}</h2><p>${d.length?'Une courte séance pour retrouver les notions déjà rencontrées.':'Les prochaines révisions apparaîtront ici. Vous pouvez aussi vous entraîner librement.'}</p>${d.length?btn('Commencer la révision','review-start'):''}</div><div class="panel"><h2>Le défi des dix questions</h2><p>Un entraînement libre tiré de la campagne, avec correction immédiate. Vous pouvez consulter les livres.</p>${btn('Lancer un défi','practice-start','','light')}<p class="fine" style="margin-top:16px">Les questions peuvent revenir d’une séance à l’autre. Ce défi n’est pas une simulation des épreuves officielles.</p></div></div>`;}
const workshops={composition:{title:'Construire une réflexion',prompt:'La dématérialisation améliore-t-elle nécessairement l’accès aux services publics locaux ?',help:'Formulez une problématique, proposez deux ou trois axes et mobilisez des exemples. Examinez à la fois les possibilités et les difficultés : inclusion, accompagnement, continuité, organisation.',checks:['Une problématique qui ouvre une discussion','Un plan qui répond au sujet','Des exemples territoriaux pertinents','Des arguments nuancés et reliés']},note:{title:'Synthétiser un dossier',prompt:'À partir des lectures du chapitre « La maison des services », préparez un plan de note sur l’accès aux services publics numériques.',help:'Travaillez à partir des documents proposés, identifiez les informations essentielles et construisez un plan synthétique. Cet atelier court ne reproduit pas un dossier complet de concours.',checks:['La commande est comprise','Les informations viennent du dossier','Les idées sont hiérarchisées','Le plan est clair et les formulations précises']},rapport:{title:'Proposer une organisation',prompt:'Valrivière souhaite améliorer l’accompagnement des habitants dans leurs démarches numériques. Proposez une organisation à partir du chapitre correspondant.',help:'Distinguez diagnostic et propositions opérationnelles. Précisez acteurs, moyens, calendrier et indicateurs. Il s’agit d’un atelier original, non d’une annale.',checks:['Un diagnostic appuyé sur les documents','Des propositions réalisables','Des acteurs et des moyens identifiés','Un suivi et une évaluation prévus']},oral:{title:'Expliquer avec clarté',prompt:'En deux minutes, expliquez le rôle d’un attaché territorial dans l’amélioration d’un service public.',help:'Préparez quelques idées, puis exprimez-les à voix haute avec votre propre chronomètre. Comparez votre réponse à la grille. Aucun enregistrement ni notation automatique.',checks:['Une réponse structurée','Des exemples concrets','Une posture de conseil et de responsabilité','Une expression compréhensible et concise']}};
function resources(){const isEx=state.profile.path==='externe',keys=isEx?['composition','note','oral']:['rapport','oral'];return `<div class="wrapper"><div class="page-intro"><span class="eyebrow">En complément de l’aventure</span><h1>Repères concours</h1><p>La campagne développe une première base de culture territoriale. Elle ne couvre pas à elle seule l’ensemble de la préparation.</p></div><div class="panel"><h2>Votre parcours : ${isEx?'externe':'troisième concours'}</h2><p>${isEx?'Composition, note sur dossier, entretien et langue vivante obligatoire.':'Rapport avec solutions opérationnelles, entretien et langue vivante facultative.'}</p><p class="fine">Cadrage à vérifier pour la session visée. Le choix du parcours ne vaut pas vérification de votre éligibilité.</p>${goBtn('Changer de parcours','settings','','light small')}<div class="divider"></div>${sources(data.sources.filter(s=>/concours|annale|cadrage/i.test(s.title)).map(s=>s.id))}</div><div class="section-title"><h2>Petits ateliers personnels</h2></div><div class="tabs">${keys.map((k,i)=>btn(workshops[k].title,'workshop',k,i?'light':'')).join('')}</div><div id="workshop">${workshop(keys[0])}</div><div class="panel"><h2>Ce que cette édition couvre</h2><p>Institutions, principes du service public, premières notions financières, obligations des agents, coopération territoriale, participation et numérique.</p><p class="fine">À compléter : approfondissements juridiques et financiers, actualité, politiques publiques sectorielles, langue vivante, entraînements longs et corrections humaines. Les exercices du jeu sont originaux ; les annales officielles restent accessibles par les liens ci-dessus.</p></div></div>`;}
function workshop(k){const w=workshops[k];return `<section class="panel"><span class="eyebrow">Atelier ${k} · Autoévaluation</span><h2>${w.title}</h2><p><strong>${w.prompt}</strong></p><p>${w.help}</p><label for="draft">Votre carnet de préparation</label><textarea id="draft" data-draft="${k}" placeholder="Vos idées, votre plan, votre réponse…">${esc(state.drafts[k]||'')}</textarea><p class="fine" id="draft-status">Enregistrement local au fil de la saisie.</p><details><summary>Ouvrir la grille d’autoévaluation</summary><ul>${w.checks.map(t=>`<li>${t}</li>`).join('')}</ul></details></section>`;}
function settingsPage(){return `<div class="wrapper"><div class="page-intro"><span class="eyebrow">À votre rythme</span><h1>Préparer votre voyage</h1></div><div class="settings-grid"><section class="panel"><h2>Votre personnage</h2><div class="field"><label for="name">Nom du personnage</label><input id="name" maxlength="40" value="${esc(state.profile.name)}"></div><div class="field"><label for="path">Parcours de préparation</label><select id="path"><option value="externe" ${state.profile.path==='externe'?'selected':''}>Concours externe</option><option value="troisieme" ${state.profile.path==='troisieme'?'selected':''}>Troisième concours</option></select></div>${btn('Enregistrer','save-profile')}</section><section class="panel"><h2>Confort de lecture</h2><div class="field"><label for="font">Taille du texte</label><select id="font">${[[1,'Standard'],[1.15,'Grande'],[1.3,'Très grande']].map(([v,t])=>`<option value="${v}" ${state.settings.font===v?'selected':''}>${t}</option>`).join('')}</select></div><label><input type="checkbox" id="motion" ${state.settings.motion?'checked':''}> Activer les transitions légères</label></section><section class="panel"><h2>Votre progression vous suit</h2><p>La sauvegarde reste dans ce navigateur. Exportez-la pour changer d’appareil ou conserver une copie.</p><div class="actions">${btn('Exporter ma sauvegarde','export')}${btn('Importer une sauvegarde','import','','light')}</div><input type="file" id="import-file" accept=".json,application/json" hidden><p class="fine" style="margin-top:15px">L’import remplacera la progression actuelle après confirmation. Une copie locale de sécurité est conservée si possible.</p></section><section class="panel"><h2>Emporter Valrivière hors ligne</h2><p>Téléchargez les scènes, les lectures et les questions. Les sites officiels externes restent accessibles en ligne seulement.</p>${btn('Préparer le mode hors ligne','offline')}<p class="status-line" id="offline-status">${esc(offlineStatus)}</p></section><section class="panel"><h2>À propos de cette édition</h2><p>Territoires ${VERSION} · ELC Studio</p><p class="fine">Valrivière et ses personnages forment un univers de jeu. Les lectures sont des synthèses pédagogiques datées. Les images ont été créées avec ImageGen. Le moteur conserve vos acquis entre les mises à jour compatibles.</p>${goBtn('Sources et codes','bag','','light')}</section></div></div>`;}
function notFound(){return `<div class="wrapper"><h1>Ce chemin n’existe pas</h1>${goBtn('Revenir au territoire','home')}</div>`;}
function render(){if(!data)return;settings();header();const views={home,chapter,mission,side,library,hero,bag,review,resources,story,journal,aftermath,settings:settingsPage};$('#main').innerHTML=(views[route.view]||notFound)();}
function openCode(id){const c=(data.codeEntries||[]).find(x=>x.id===id);if(!c)return;bookReturnFocus=document.activeElement;$('#modal').innerHTML=`<section class="modal-panel" role="dialog" aria-modal="true" aria-labelledby="code-title"><header class="modal-head"><span class="eyebrow">${esc(c.code)} · ${esc(c.article)}</span><button class="iconbtn" data-action="closebook" aria-label="Fermer le repère">${icon('close')}</button></header><div class="book-content"><h2 id="code-title">${esc(c.title)}</h2><p>${esc(c.summary)}</p><p class="fine">Repère reformulé pour l’apprentissage. Le lien officiel permet de consulter le texte intégral.</p>${sources(c.sourceIds)}</div><footer class="modal-foot">${btn('Revenir à la question','closebook','','light')}</footer></section>`;$('#modal').hidden=false;document.body.style.overflow='hidden';$('#modal button').focus();}
function openBook(id){const b=data.books.find(x=>x.id===id);if(!b)return;bookReturnFocus=document.activeElement;E.collect(data,state,id);persist();header();$('#modal').innerHTML=`<section class="modal-panel" role="dialog" aria-modal="true" aria-labelledby="book-title"><header class="modal-head"><span class="eyebrow">${esc(b.domain)} · Le carnet de Valrivière</span><button class="iconbtn" data-action="closebook" aria-label="Fermer le livre">${icon('close')}</button></header><div class="book-content" tabindex="0"><span class="tag ${b.optional?'gold':''}">${b.optional?'Lecture de découverte':'Lecture essentielle'}</span><h2 id="book-title" style="margin-top:20px">${esc(b.title)}</h2>${b.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="keypoints"><strong>À retenir pour agir</strong><ul>${b.keyPoints.map(p=>`<li>${esc(p)}</li>`).join('')}</ul></div><details><summary>Sources et références · 30 octobre 2026</summary>${sources(b.sourceIds)}<p class="fine">Synthèse pédagogique originale. Pour une situation réelle, consulter le texte applicable.</p></details><div class="divider"></div>${btn(state.read.includes(id)?'Lecture terminée ✓':'J’ai terminé cette lecture','read',id)}</div><footer class="modal-foot"><small>${state.collected.includes(id)?'Conservé dans votre sacoche':''}</small>${btn('Retour au dossier','closebook','','light small')}</footer></section>`;$('#modal').hidden=false;document.body.style.overflow='hidden';$('#modal button').focus();}
function closeBook(refresh=true){if(!$('#modal'))return;const was=!$('#modal').hidden;$('#modal').hidden=true;document.body.style.overflow='';if(refresh&&was){if(quiz)renderQuiz();else render();}if(was&&bookReturnFocus?.isConnected)bookReturnFocus.focus();}
function download(name,text){const u=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);}
async function prepareOffline(){const target=$('#offline-status');if(!('serviceWorker' in navigator)){target.textContent='Ce navigateur ne prend pas en charge le mode hors ligne.';return;}target.textContent='Téléchargement des ressources…';try{const reg=await navigator.serviceWorker.register('./sw.js');await navigator.serviceWorker.ready;const worker=reg.active||reg.waiting||reg.installing;const ch=new MessageChannel();const result=await new Promise((resolve,reject)=>{const t=setTimeout(()=>reject(Error('Délai dépassé')),60000);ch.port1.onmessage=e=>{clearTimeout(t);resolve(e.data);};worker.postMessage({type:'CACHE_ALL'},[ch.port2]);});if(!result.ok)throw Error(result.error||'Téléchargement incomplet');offlineStatus='Prêt : lectures, questions et illustrations téléchargées.';target.textContent=offlineStatus;notify('Valrivière est prête pour le voyage.');}catch(e){offlineStatus='Téléchargement incomplet. Réessayez avec une connexion.';target.textContent=offlineStatus;}}
document.addEventListener('click',async e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.go){nav(t.dataset.go,t.dataset.id||'');return;}if(t.dataset.answer!==undefined&&quiz&&quiz.feedback===null){const choice=Number(t.dataset.answer),qid=quiz.ids[quiz.pos];quiz.selected=choice;quiz.feedback=E.answer(data,state,qid,choice);quiz.results.push(quiz.feedback);persist();renderQuiz();return;}const a=t.dataset.action,id=t.dataset.id;try{switch(a){case'story-next':{const n=data.campaign.missions[id];if(n){state.narrative.dialogues[id]=Math.min(n.opening.length,(state.narrative.dialogues[id]||0)+1);persist();render();}break;}case'document':openDocument(id);break;case'begin-story':state.narrative.started=true;state.narrative.mode='campaign';persist();nav('mission',nextMission()?.id||data.chapters[0].missions[0].id);break;case'story-mode':state.narrative.mode=state.narrative.mode==='campaign'?'free':'campaign';persist();render();break;case'book':openBook(id);break;case'code':openCode(id);break;case'closebook':closeBook();break;case'read':E.markRead(data,state,id);persist();closeBook();notify('Lecture ajoutée à votre parcours.');break;case'start':{const m=E.getMission(data,id);if(!m.requiredBooks.every(b=>state.read.includes(b)))return;startQuiz(m.questions.map(q=>q.id),'mission',id);break;}case'start-side':{const s=data.sideQuests.find(x=>x.id===id);startQuiz([s.question.id],'side',id);break;}case'nextq':if(quiz.feedback===false&&quiz.kind!=='practice'){quiz.feedback=null;quiz.selected=null;renderQuiz();}else{quiz.pos++;quiz.feedback=null;quiz.selected=null;renderQuiz();}break;case'quitquiz':quiz=null;render();break;case'complete':E.complete(data,state,id);persist();quiz=null;nav('aftermath',id);notify('Dossier résolu. Votre carnet s’enrichit.');break;case'complete-side':E.completeSide(data,state,id);persist();quiz=null;nav('chapter',data.sideQuests.find(s=>s.id===id).chapterId);notify('Un nouveau souvenir rejoint votre collection.');break;case'collection':bookFilters.collection=!bookFilters.collection;render();break;case'bag-tab':for(const k of ['books','codes','sources'])$('#bag-'+k).hidden=k!==id;document.querySelectorAll('[data-action="bag-tab"]').forEach(b=>b.classList.toggle('light',b.dataset.id!==id));break;case'review-start':startQuiz(E.due(data,state).map(q=>q.id),'review','');break;case'practice-start':{const ids=E.index(data).missions.flatMap(m=>m.questions.map(q=>q.id));for(let i=ids.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]];}startQuiz(ids.slice(0,10),'practice','');break;}case'workshop':$('#workshop').innerHTML=workshop(id);break;case'save-profile':state.profile.name=$('#name').value.trim().slice(0,40)||'Camille';state.profile.path=$('#path').value==='troisieme'?'troisieme':'externe';persist();notify('Votre personnage est prêt.');break;case'export':download('territoires-sauvegarde.json',JSON.stringify(state,null,2));break;case'import':$('#import-file').click();break;case'offline':await prepareOffline();break;}}catch(err){notify('Action impossible : '+err.message);}});
document.addEventListener('input',e=>{if(e.target.id==='book-search'){bookFilters.query=e.target.value;$('#book-results').innerHTML=filteredBooks().map(bookTile).join('')||'<p>Aucun livre ne correspond à votre recherche.</p>';$('#book-count').textContent=filteredBooks().length+' ouvrages';}if(e.target.dataset.draft){state.drafts[e.target.dataset.draft]=e.target.value.slice(0,30000);const ok=persist();$('#draft-status').textContent=ok?'Brouillon enregistré sur cet appareil.':'Enregistrement indisponible.';}});
document.addEventListener('change',async e=>{if(e.target.id==='book-domain'){bookFilters.domain=e.target.value;render();}if(e.target.id==='font'){state.settings.font=Number(e.target.value);settings();persist();}if(e.target.id==='motion'){state.settings.motion=e.target.checked;settings();persist();}if(e.target.id==='import-file'){const f=e.target.files[0];if(!f)return;try{if(f.size>1000000)throw Error('Fichier trop volumineux');const next=E.restore(data,JSON.parse(await f.text()));if(!confirm('Remplacer votre progression par celle de '+next.profile.name+' ?'))return;try{localStorage.setItem(KEY+'.backup',JSON.stringify(state));}catch{}state=next;persist();render();notify('Sauvegarde importée.');}catch(err){notify('Import refusé : '+err.message);}e.target.value='';}});
document.addEventListener('keydown',e=>{if($('#modal').hidden)return;if(e.key==='Escape'){closeBook();return;}if(e.key==='Tab'){const els=Array.from($('#modal').querySelectorAll('button,a,summary,[tabindex="0"]')).filter(x=>x.getClientRects().length);const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
window.addEventListener('hashchange',parseRoute);
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue)notify('La progression a changé dans un autre onglet. Rechargez avant de continuer.');});
async function boot(){try{const r=await fetch('./content.json');if(!r.ok)throw Error('Contenu indisponible');data=await r.json();sourceLookup=Object.fromEntries(data.sources.map(s=>[s.id,s]));state=E.fresh();try{const old=localStorage.getItem(KEY);if(old)state=E.restore(data,JSON.parse(old));}catch{notify('La sauvegarde n’a pas pu être relue. Votre ancien fichier local n’a pas été effacé.');}parseRoute();if('serviceWorker' in navigator){navigator.serviceWorker.getRegistration().then(async reg=>{if(reg&&'caches'in window){const c=await caches.open('territoires-v1.1.0');if(await c.match(new URL('./content.json',location.href).href))offlineStatus='Ressources hors ligne déjà présentes.';}}).catch(()=>{});}}catch(err){$('#main').innerHTML=`<div class="loading"><h1>Le carnet n’a pas pu s’ouvrir</h1><p>${esc(err.message)}</p><button class="btn" onclick="location.reload()">Réessayer</button></div>`;}}
function characterName(id){return data.campaign.characters.find(c=>c.id===id)?.name||id;}
function personal(text){return esc(text).replaceAll('{name}',esc(state.profile.name));}
function storySeen(id){const n=data.campaign?.missions[id];return !n||(state.narrative.dialogues[id]||0)>=n.opening.length;}
function home(){if(!data.campaign)return originalHome();const next=nextMission(),ended=state.completed.length===18;return scene({scene:ended?'opening':'manufacture',domain:'Une année à Valrivière'},data.campaign.title,ended?'La maison accueille ses premiers habitants. Votre histoire reste dans le carnet.':'Une manufacture fermée. Des habitants qui attendent. Une année pour construire un service public avec votre équipe.',goBtn(ended?'Retrouver mon histoire':state.narrative.started?'Poursuivre la campagne':'Commencer l’histoire',ended?'journal':state.narrative.started?'mission':'story',ended?'':state.narrative.started?next?.id||'':'','gold')+goBtn('Mon carnet','journal','','ghost'))+`<div class="wrapper"><div class="ribbon"><div><span class="eyebrow">${esc(state.profile.name)} · Chargé de mission</span><h2>${state.completed.length} / 18 étapes accomplies</h2><p>${next?esc(data.campaign.missions[next.id].time)+' — '+esc(next.title):'La campagne est terminée. Les révisions continuent.'}</p></div>${goBtn('Bibliothèque','library','','light')}</div><div class="section-title"><div><span class="eyebrow">Les six actes de votre année</span><h2>Une ville, une histoire commune</h2></div></div><div class="chapter-grid">${data.chapters.map((c,i)=>`<button class="chapter-card" data-go="chapter" data-id="${c.id}"><div class="chapter-image"><img src="./assets/${data.campaign.missions[c.missions[0].id].scene}.webp" alt="" loading="lazy"><span class="chapter-number">0${i+1}</span></div><div class="card-copy"><span class="eyebrow">${esc(c.domain)}</span><h3>${esc(c.title)}</h3><p>${esc(data.campaign.missions[c.missions[0].id].time)}</p><div class="row"><small>${c.missions.filter(m=>state.completed.includes(m.id)).length} / 3 dossiers</small>${icon('arrow')}</div></div></button>`).join('')}</div><div class="ribbon"><p>Les connaissances se construisent dans les dossiers et se consolident en revenant sur les notions.</p>${goBtn('Réviser mes acquis','review','','light')}</div></div>`;}
function story(){return scene({scene:'office',domain:'Prologue'},'Votre premier rendez-vous','Annexe administrative · Votre premier matin','',true)+`<div class="wrapper story-width"><span class="eyebrow">Une année pour faire ses preuves</span><h2>Bienvenue, ${esc(state.profile.name)}.</h2>${data.campaign.prologue.map(p=>`<p class="story-paragraph">${personal(p)}</p>`).join('')}<div class="letter"><span class="eyebrow">Votre lettre de mission</span><h3>Relier les services, éclairer les décisions</h3><p>Vous préparez les dossiers de la manufacture auprès de la direction générale. Vous écoutez, vérifiez les documents et proposez des réponses. Les décisions appartiennent aux autorités compétentes.</p><p>Votre nom dans l’histoire : <strong>${esc(state.profile.name)}</strong></p>${goBtn('Personnaliser mon personnage','settings','','light small')}</div><div class="actions">${btn('Rencontrer l’équipe','begin-story')}${goBtn('Retour à Valrivière','home','','light')}</div></div>`;}
function storyPanel(m,n){const pos=Math.min(state.narrative.dialogues[m.id]||0,n.opening.length),line=n.opening[pos],seen=pos>=n.opening.length;return `<section class="narrative panel" aria-label="Scène du dossier"><div class="row"><span class="eyebrow">${esc(n.time)} · ${esc(n.place)}</span><span class="tag">${seen?'Échange terminé':(pos+1)+' / '+n.opening.length}</span></div>${line?`<div class="dialogue"><span class="speaker">${esc(line.speaker)}</span><p>${personal(line.text)}</p></div>${btn(pos===n.opening.length-1?'Ouvrir le dossier':'Poursuivre l’échange','story-next',m.id)}`:`<h2>Votre mission</h2><p>${personal(n.objective)}</p><details><summary>Relire l’échange</summary>${n.opening.map(l=>`<p><strong>${esc(l.speaker)}</strong> — ${personal(l.text)}</p>`).join('')}</details>`}<div class="divider"></div><div class="row"><div><span class="eyebrow">Pièce du dossier</span><h3>${esc(n.document.title)}</h3></div>${btn(state.narrative.documents.includes(m.id)?'Relire la pièce':'Lire et conserver','document',m.id,'light')}</div></section>`;}
function openDocument(id){const n=data.campaign?.missions[id];if(!n)return;if(!state.narrative.documents.includes(id))state.narrative.documents.push(id);persist();bookReturnFocus=document.activeElement;$('#modal').innerHTML=`<section class="modal-panel" role="dialog" aria-modal="true" aria-labelledby="document-title"><header class="modal-head"><span class="eyebrow">Pièce de votre campagne · ${esc(n.time)}</span><button class="iconbtn" data-action="closebook" aria-label="Fermer le document">${icon('close')}</button></header><article class="book-content letter"><h2 id="document-title">${esc(n.document.title)}</h2><p>${personal(n.document.text)}</p><div class="divider"></div><small>Conservé dans votre carnet de campagne.</small></article><footer class="modal-foot">${btn('Retour au dossier','closebook','','light')}</footer></section>`;$('#modal').hidden=false;document.body.style.overflow='hidden';$('#modal button').focus();}
function questionScene(q,m){if(!data.campaign||!['mission','side'].includes(quiz.kind))return '';const n=m?data.campaign.missions[m.id]:data.campaign.sideQuests[quiz.id];if(!n)return '';const text=m?n.questionContexts[m.questions.findIndex(x=>x.id===q.id)]:n.questionContext;return `<aside class="question-scene">${m?`<img src="./assets/${n.scene}.webp" alt="${esc(n.place)}"><span class="eyebrow">${esc(n.place)}</span>`:''}<p>${personal(text)}</p></aside>`;}
function aftermath(){const m=E.getMission(data,route.id),n=data.campaign?.missions[route.id];if(!m||!n||!state.completed.includes(m.id))return notFound();const next=nextMission();return scene({scene:n.scene,domain:'Le projet avance'},'Une étape franchie',m.title,'',true)+`<div class="wrapper story-width"><div class="letter"><span class="eyebrow">Ce que votre travail a permis</span><h2>${esc(n.document.title)}</h2><p>${personal(n.outcome)}</p></div><p class="story-paragraph">${personal(n.hook)}</p><div class="actions">${next?goBtn('La suite de l’histoire','mission',next.id):goBtn('Lire l’épilogue','journal')}${goBtn('Mon carnet','journal','','light')}</div></div>`;}
function journal(){const ms=E.index(data).missions,next=nextMission(),ended=state.completed.length===ms.length;return `<div class="wrapper story-width"><div class="page-intro"><span class="eyebrow">${esc(state.profile.name)} · Mémoire de votre année</span><h1>Le carnet de campagne</h1><p>Vos rencontres, les pièces conservées et les étapes accomplies restent ici.</p></div>${ended?`<article class="panel"><img class="journal-image" src="./assets/opening.webp" alt="La manufacture réhabilitée ouvre aux habitants"><h2>Une porte ouverte sur la suite</h2><p>Après les travaux, les vérifications et les décisions conduites par les services compétents, la maison ouvre ses portes. Lucie accueille les premiers visiteurs. Marianne vous rejoint : « Nous n’avons pas tout résolu. Mais nous savons désormais ce que nous devons suivre et améliorer. »</p><p>Votre année s’achève avec un carnet rempli de questions devenues connaissances. La suite du service public commence avec les habitants.</p>${goBtn('Entretenir mes acquis','review')}</article>`:`<div class="panel"><span class="eyebrow">Votre prochaine étape</span><h2>${esc(next?.title||'Reprendre le prologue')}</h2><p>${esc(next?data.campaign.missions[next.id].objective:'')}</p>${next?goBtn('Poursuivre','mission',next.id):''}${goBtn('Relire le prologue','story','','light')}</div>`}<details class="panel"><summary>Les visages de Valrivière</summary>${data.campaign.characters.map(c=>`<article class="source-item"><h3>${esc(c.name)}</h3><strong>${esc(c.role)}</strong><p>${esc(c.description)}</p></article>`).join('')}</details>${state.side.length?`<section class="panel"><h2>Rencontres au fil du chemin</h2>${data.sideQuests.filter(x=>state.side.includes(x.id)).map(x=>`<h3>${esc(x.title)}</h3><p>${esc(data.campaign.sideQuests[x.id].outcome)}</p>`).join('')}</section>`:''}<h2>Les traces de votre parcours</h2>${ms.filter(m=>state.completed.includes(m.id)||state.narrative.documents.includes(m.id)).map(m=>{const n=data.campaign.missions[m.id];return `<article class="panel"><span class="eyebrow">${esc(n.time)} · ${state.completed.includes(m.id)?'Accompli':'En cours'}</span><h3>${esc(m.title)}</h3>${state.completed.includes(m.id)?`<p>${personal(n.outcome)}</p>`:''}<div class="actions">${state.narrative.documents.includes(m.id)?btn(esc(n.document.title),'document',m.id,'light small'):''}${goBtn('Revenir au dossier','mission',m.id,'light small')}</div></article>`;}).join('')||'<p>Votre première rencontre ouvrira ce carnet.</p>'}<details class="panel"><summary>Choisir mon rythme</summary><p>La campagne suit les dossiers dans l’ordre. L’exploration libre permet de travailler chaque domaine indépendamment, avec des scènes situées à différentes dates.</p>${btn(state.narrative.mode==='campaign'?'Passer en exploration libre':'Revenir à la campagne chronologique','story-mode','','light')}<p class="fine">Vos acquis et sauvegardes sont conservés. Les anciennes sauvegardes démarrent en exploration libre.</p></details></div>`;}

boot();
